const crypto = require('crypto');
const req = $input.first().json;
const b = req.body || {};
const sig = (req.headers || {})['x-speedhack-signature'];
const digest = crypto.createHash('sha256').update(String(b.body || ''), 'utf8').digest('hex');
const parts = [b.outreach_id, b.prospect_id, b.channel, digest].join('\n');
const expected = 'sha256=' + crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(parts, 'utf8').digest('hex');
const ok = !!sig && sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!ok) throw new Error('bad signature: draft refused');
if (b.stage !== 'draft') throw new Error('unexpected stage');
return [{ json: { ...b, verified: true } }];

const crypto = require('crypto');
const req = $input.first().json;
const b = req.body || {};
const sig = (req.headers || {})['x-speedhack-signature'];
const draft = $('Verify draft signature').first().json;
if (!b.approved_by || String(b.approved_by).trim() === '') throw new Error('approved_by is required');
if (b.stage !== 'approval') throw new Error('unexpected stage');
if (b.outreach_id !== draft.outreach_id) throw new Error('outreach_id mismatch');
const digest = crypto.createHash('sha256').update(String(draft.body || ''), 'utf8').digest('hex');
const parts = [draft.outreach_id, draft.prospect_id, draft.channel, String(b.approved_by).trim(), digest].join('\n');
const expected = 'sha256=' + crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(parts, 'utf8').digest('hex');
const ok = !!sig && sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
return [{ json: { approved: ok, outreach_id: draft.outreach_id, prospect_id: draft.prospect_id, channel: draft.channel, approved_by: String(b.approved_by).trim(), body: draft.body, demo_data: true } }];

const crypto = require('crypto');
const j = $input.first().json;
const sentAt = new Date().toISOString();
const parts = [j.outreach_id, 'sent', sentAt].join('\n');
const signature = 'sha256=' + crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(parts, 'utf8').digest('hex');
return [{ json: { outreach_id: j.outreach_id, status: 'sent', sent_at: sentAt, transport: 'mock', demo_data: true, note: 'Mock send: no real email or WhatsApp was sent.', signature } }];
